    for r in range(h - 3):
        for c in range(w - 3):
            if all(grid[rr][cc] == 3 for rr in range(r, r + 4) for cc in range(c, c + 4)):
                top, left = r, c
                break
        if top is not None:
            break
    if top is None:
        raise ValueError('4x4 marker not found')
    return [[grid[h - 1 - (top + i)][w - 1 - (left + j)] for j in range(4)] for i in range(4)]
